'use strict';

/* Real W5 and W6 draft commit snapshots are checked out separately by CI.
 * W3's original synthetic files are generated by the merged native Python runner.
 * The tests never copy unmerged worker sources into the coordinator branch.
 */
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');
const Bridge = require('./bridge.cjs');

const dataDir = process.env.COORD_W3_FIXTURES;
const w5File = process.env.COORD_W5_CONTRACTS;
const w5Adapters = process.env.COORD_W5_ADAPTERS;
const w6File = process.env.COORD_W6_RENDERER;
if (![dataDir, w5File, w5Adapters, w6File].every(p => typeof p === 'string' && fs.existsSync(p))) {
  throw Error('Independent W3 fixtures and pinned W5/W6 source paths required; do not use bundled mock validators.');
}
const W5 = require(path.resolve(w5File));
const W5Adapter = require(path.resolve(w5Adapters));
const W6 = require(path.resolve(w6File));
const load = name => Bridge.fromDirectory(path.join(dataDir, name));
const copy = value => structuredClone(value);
const SMALL = load('small');
const MISSING = load('missing');
const LARGE = load('large');

test('source outputs are genuine W3 v1 engineering results with complete graph ledgers', () => {
  for (const sample of [SMALL, MISSING, LARGE]) {
    assert.equal(sample.envelope.producer.workstream_id, 'W3');
    assert.equal(sample.envelope.evaluation_role, 'engineering_only');
    assert.equal(sample.envelope.publication_eligible, false);
    assert.equal(sample.receipt.heldout_transcripts_opened, 0);
    assert.equal(sample.receipt.graph.edge_count, sample.edges.length);
    assert.equal(sample.receipt.graph.n_nodes, sample.population.eligible);
    assert.match(sample.graph_policy_sha256, /^[a-f0-9]{64}$/);
    assert.equal(sample.receipt.representation.id, sample.envelope.models[0].representation_id);
    assert.ok(sample.envelope.limitations.some(x => /policy|diplomatic|politic/i.test(x.description)));
  }
  assert.equal(SMALL.population.eligible, 24);
  assert.equal(MISSING.population.excluded, 1);
  assert.equal(MISSING.population.unavailable, 1);
  assert.equal(LARGE.population.eligible, 96);
});

test('actual W5 accepts all unmodified W3 envelopes, including complete excluded rows', () => {
  for (const cohort of [SMALL, MISSING, LARGE]) {
    assert.equal(W5.validateParallel(cohort.envelope), cohort.envelope);
    const view = W5.fromParallel(Bridge.forW5(cohort).envelope);
    assert.equal(view.kind, 'parallel');
    assert.equal(view.models.length, 2);
    assert.equal(view.source.schema, 'synthetic.v1');
    assert.equal(view.observations.length, cohort.envelope.observations.length);
    for (const model of view.models) {
      assert.equal(model.execution, 'offline_only');
      assert.equal(model.rows.length, cohort.envelope.observations.length);
    }
  }
  const modeled = W5.fromParallel(MISSING.envelope);
  assert.equal(modeled.models[0].rows.filter(r => r.status === 'excluded').length, 1);
  assert.equal(modeled.coverage.unavailable_sources, 1);
});

test('W5 SHA-256 archive/replay retains W3 full source/assignment denominators', async () => {
  const archived = await W5Adapter.packParallel([MISSING.envelope, SMALL.envelope]);
  const restored = await W5Adapter.restoreParallel(archived);
  assert.deepEqual(restored[0], MISSING.envelope);
  assert.deepEqual(restored[1], SMALL.envelope);
  const fake = JSON.parse(archived);
  fake.payload_json = fake.payload_json.replace('fictional', 'modified');
  await assert.rejects(() => W5Adapter.restoreParallel(JSON.stringify(fake)), /checksum/i);
});

test('W5 never implies spectral vs diffusion are comparable fitted partitions', () => {
  const view = W5.fromParallel(SMALL.envelope);
  const [a,b] = view.models;
  const compare = W5.compare(view, view, a.id, b.id);
  assert.equal(compare.identical_population, true);
  assert.equal(compare.numerical_comparison_permitted, false);
  const via = W5Adapter.compareViews(view, view, a.id, b.id);
  assert.equal(via.numerical_comparison_permitted, false);
  assert.match(via.reason, /mixtures|graph distances|consensus/i);
});

test('W6 renders a W3 graph with explicit kNN affinity (never falsely called cosine)', () => {
  const x = Bridge.forW6Network(SMALL);
  assert.equal(x.status, 'ready');
  assert.equal(x.panel.nodes.length, 24);
  assert.equal(x.panel.edges.length, SMALL.receipt.graph.edge_count);
  assert.equal(x.panel.graph.threshold, 0);
  assert.match(x.panel.graph.metric, /^gaussian_affinity_on_euclidean_knn$/);
  assert.match(x.panel.graph.selection_rule, /no global edge-weight threshold/);
  assert.ok(x.panel.edges.every(edge =>
    edge.eligible_pairs === 1 &&
    edge.duplicate_sensitivity === 'not_assessed' &&
    edge.agenda_sensitivity === 'not_assessed'));
  const view = W6.renderPanel(SMALL.envelope, x.panel);
  assert.equal(view.status, 'ready');
  assert.match(view.svg, /<svg/);
  assert.match(view.html, /not.*alliance|alliance/i);
  assert.match(view.html, /gaussian_affinity_on_euclidean_knn/);
  assert.match(view.html, /Source observations/);
  assert.doesNotMatch(view.html, /policy position probability/);
});

test('W6 explicitly cannot accept source-complete W3 24+1 frame; no lossy relabeling', () => {
  assert.equal(W5.validateParallel(MISSING.envelope), MISSING.envelope);
  const x = Bridge.forW6Network(MISSING);
  assert.equal(x.status, 'blocked_contract');
  assert.equal(x.panel, null);
  assert.match(x.reason, /excluded\/model rows/);
  assert.equal(MISSING.envelope.observations.length, 25);
  assert.equal(MISSING.envelope.results.length, 50);
  assert.equal(MISSING.envelope.coverage.models[0].excluded, 1);
  assert.throws(() => W6.validateEnvelope(MISSING.envelope), /Result row counts do not reconcile/);
});

test('96-node W3 graph is fully accounted for and W6 receives a WITHHELD state', () => {
  assert.equal(W5.validateParallel(LARGE.envelope), LARGE.envelope);
  const x = Bridge.forW6Network(LARGE);
  assert.equal(x.status, 'withheld');
  assert.equal(x.panel.status, 'withheld');
  assert.equal(x.panel.nodes, undefined);
  assert.equal(x.panel.coverage.eligible, 96);
  assert.equal(x.panel.coverage.included, 0);
  assert.match(x.panel.reason, /50/);
  const view = W6.renderPanel(LARGE.envelope, x.panel);
  assert.equal(view.status, 'withheld');
  assert.doesNotMatch(view.html, /data-ev-inspect=/);
  assert.match(view.svg, /WITHHELD/);
});

test('metadata/source identity drift and missing graph edges fail closed', () => {
  const a = copy(SMALL);
  a.envelope.upstream.source_sha256 = 'a'.repeat(64);
  assert.throws(() => Bridge.validate(a), /source\/selection lineage mismatch/);
  const b = copy(SMALL);
  b.edges[0].from_text_sha256 = 'b'.repeat(64);
  assert.throws(() => Bridge.validate(b), /edge source hash/);
  const c = copy(SMALL);
  c.edges.pop();
  assert.throws(() => Bridge.validate(c), /edge count/);
  const d = copy(SMALL);
  d.edges.push(copy(d.edges[0]));
  d.receipt.graph.edge_count += 1;
  assert.throws(() => Bridge.validate(d), /duplicate undirected edge/);
  const e = copy(SMALL);
  e.fitted.spectral.labels[0] += 5;
  assert.throws(() => Bridge.validate(e), /spectral interchange label/);
});

test('invalid Gaussian distance/weight and graph inventory are refused', () => {
  const a = copy(SMALL);
  a.edges[0].weight *= .5;
  assert.throws(() => Bridge.validate(a), /Gaussian kernel/);
  const b = copy(SMALL);
  b.receipt.graph.component_sizes = [2,3];
  assert.throws(() => Bridge.validate(b), /component ledger/);
  const c = copy(SMALL);
  c.edges[0].metric_distance = -1;
  assert.throws(() => Bridge.validate(c), /distance\/affinity/);
  const d = copy(SMALL);
  d.edges[0].graph_policy_sha256 = '0'.repeat(64);
  assert.throws(() => Bridge.validate(d), /Inconsistent graph policy/);
});

test('checksum mismatch is detected before any W5 or W6 render', () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'w3-integrity-'));
  try {
    const src = path.join(dataDir, 'small');
    for (const name of fs.readdirSync(src)) {
      if (fs.statSync(path.join(src, name)).isFile())
        fs.copyFileSync(path.join(src,name),path.join(dir,name));
    }
    const file=path.join(dir,'receipt.json');
    fs.appendFileSync(file,' ');
    assert.throws(() => Bridge.fromDirectory(dir), /checksum mismatch/);
  } finally {
    fs.rmSync(dir, {recursive:true,force:true});
  }
});

test('the shared adapter never promotes private development or invents source evidence', () => {
  const a=copy(SMALL);
  a.envelope.cohort.split='development';
  assert.throws(() => Bridge.validate(a), /synthetic engineering/);
  const b=Bridge.forW6Network(SMALL);
  assert.ok(b.panel.nodes.every(n => /Unattributed/.test(n.affiliation_status)));
  assert.ok(b.panel.warnings.some(w=>/NOT been assessed/.test(w)));
  assert.ok(!b.panel.nodes.some(n=>Object.hasOwn(n,'text')));
  assert.ok(!b.panel.edges.some(n=>Object.hasOwn(n,'stance')));
});

test('W6 native prototype is a synthetic-only interface, not a source production release', () => {
  assert.equal(W6.VERSION !== undefined, true);
  assert.equal(typeof W6.renderPanel, 'function');
  const x = Bridge.forW6Network(SMALL);
  assert.equal(x.panel.coverage.frame, 24);
  assert.equal(x.panel.coverage.missing, 0);
  assert.equal(x.panel.identity.source_hash_basis, 'synthetic');
});
